package com.lifeos.projects.dto;import com.lifeos.projects.*;import java.time.*;public record ProjectResponse(Long id,String name,String description,ProjectStatus status,LocalDate startDate,LocalDate targetDate,LocalDateTime createdAt,LocalDateTime updatedAt){public static ProjectResponse from(Project p){return new ProjectResponse(p.getId(),p.getName(),p.getDescription(),p.getStatus(),p.getStartDate(),p.getTargetDate(),p.getCreatedAt(),p.getUpdatedAt());}}
